```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const s = line.trim();
    let count = 0;
    let i = 0;
    const n = s.length;

    while (i < n) {
        let j = i;
        while (j < n && s[j] === s[i]) {
            j++;
        }
        const runLength = j - i;
        if (runLength % 2 === 0) {
            count++;
        }
        i = j;
    }

    console.log(count);
});
