const fs = require('fs');

function solve() {
    const input = fs.readFileSync('/dev/stdin', 'utf8').trim();
    const s = input;

    // We need to find the minimum number of insertions to make all runs of identical characters have odd length.
    // A run is a maximal sequence of consecutive identical characters.
    // If a run has even length, we need to insert at least one character to break it into two runs of odd length.
    // But inserting a character might affect adjacent runs.

    // Let's think about this differently.
    // We can process the string and for each maximal run of identical characters:
    // - If the run length is odd, no insertion is needed for that run.
    // - If the run length is even, we need to insert at least one character.
    //   But where do we insert? If we insert a character of a different type in the middle, 
    //   it splits the even-length run into two runs. For example, "TT" -> "TAT" gives runs "T", "A", "T" all odd.
    //   However, we need to be careful: inserting a character might merge with adjacent runs if the adjacent run has the same character.

    // Actually, let's reconsider. The key insight is:
    // For each maximal run of identical characters of length L:
    // - If L is odd, it's fine.
    // - If L is even, we need to insert at least one character. The best place is to insert a character of a different type 
    //   somewhere in the run. This will split the run into two parts. To minimize the number of insertions, 
    //   we want each resulting run to have odd length. 
    //   If we insert one character, the even-length run L is split into two runs of lengths a and b where a + b = L - 1 (since one position is taken by the inserted char).
    //   Wait, no. If we have a run of length L (even), and we insert one character of a different type at position i (0-indexed within the run), 
    //   then we get two runs of the original character: one of length i and one of length L - 1 - i.
    //   We need both i and L - 1 - i to be odd. Since L is even, L - 1 is odd. So we need i odd and L - 1 - i odd.
    //   i odd and (odd - i) odd means i must be odd. So we can choose i = 1, 3, 5, ... as long as i < L.
    //   Since L >= 2 (even), we can always choose i = 1. So one insertion per even-length run is sufficient.

    // But wait, what if inserting a character causes it to merge with an adjacent run? 
    // For example, consider "AATT". The runs are "AA" (length 2, even) and "TT" (length 2, even).
    // If we insert a 'C' in the middle of "AA": "ACAT T" -> runs: "A", "C", "A", "TT". Now "TT" is still even.
    // We need to fix "TT" too. So we insert another character, say 'G': "ACATGT" -> runs: "A", "C", "A", "T", "G", "T". All odd.
    // Total insertions: 2.

    // What if we insert a character that is the same as the adjacent run's character? 
    // For example, "AATT". If we insert 'A' in the middle of "TT": "AATAT" -> runs: "AAA", "T". "AAA" is odd, "T" is odd. 
    // Wait, "AATAT": the first three are 'A', 'A', 'A' -> run of length 3 (odd). Then 'T', then 'A', then 'T'. 
    // Actually, "AATAT" has runs: "AAA" (positions 0-2), "T" (position 3), "A" (position 4), "T" (position 5)? No, the string is "AATAT" which is 5 chars: A, A, T, A, T.
    // Runs: "AA" (length 2, even), "T" (length 1, odd), "A" (length 1, odd), "T" (length 1, odd).
    // So "AA" is still even. That didn't help.

    // Let me re-examine. The problem is that we need to make ALL runs have odd length.

    // Let's think greedily. We process the string from left to right.
    // We maintain the current run length. When we finish a run (i.e., the next character is different or we reach the end), 
    // we check if the run length is even. If it is, we need to insert a character.
    // But where? The optimal strategy is to insert a character of a different type at the end of the even-length run, 
    // but that would create a new run of length 1 (odd) and the original run remains even. That doesn't work.

    // Actually, the standard solution for this problem is:
    // For each maximal run of identical characters:
    // - If the length is even, we need to insert one character. 
    // - The total number of insertions is the number of even-length runs.

    // Let's verify with the examples.
    // Example 1: "GTTAAAG"
    // Runs: "G" (1, odd), "TT" (2, even), "AAA" (3, odd), "G" (1, odd).
    // Number of even-length runs: 1. Output: 1. Matches.

    // Example 2: "AACCAACCAAAAC"
    // Let's break it down:
    // "AA" (2, even), "CC" (2, even), "AA" (2, even), "CC" (2, even), "AAA" (3, odd), "A" (1, odd), "C" (1, odd).
    // Wait, let me re-parse "AACCAACCAAAAC":
    // A, A, C, C, A, A, C, C, A, A, A, A, C
    // Runs: "AA" (2), "CC" (2), "AA" (2), "CC" (2), "AAAA" (4), "C" (1).
    // Even-length runs: "AA", "CC", "AA", "CC", "AAAA" -> 5 even-length runs.
    // Output: 5. Matches.

    // So the solution is simply to count the number of maximal runs of identical characters that have even length.

    let count = 0;
    let i = 0;
    const n = s.length;

    while (i < n) {
        let j = i;
        while (j < n && s[j] === s[i]) {
            j++;
        }
        const runLength = j - i;
        if (runLength % 2 === 0) {
            count++;
        }
        i = j;
    }

    console.log(count);
}

solve();
